13.2 State Examples by Level

13.2.1 System State Examples
System State: E-commerce Platform
  - Feature flags: { "new_checkout_ui": true, "recommendations_enabled": false }
  - Global configuration: { "maintenance_mode": false, "max_cart_items": 100 }
  - Resource availability: { "payment_gateway_status": "operational", "email_service_status": "operational" }
  - Operational mode: "normal"
  - Performance metrics: { "p95_latency_ms": 250, "throughput_rps": 850 }


13.2.2 Component State Examples
Component State: API Service
  - Connection pool: { "active_connections": 45, "available_connections": 55 }
  - In-memory cache: { "user_cache_size": 1000, "product_cache_size": 5000 }
  - Rate limiting: { "requests_per_minute": 5000, "current_rate": 3200 }
  - Health status: { "status": "healthy", "last_check": "2024-01-15T10:30:00Z" }


13.2.3 Session State Examples
Session State: User Session
  - Session ID: "sess_abc123"
  - User ID: "user_456"
  - Authentication: { "authenticated": true, "auth_time": "2024-01-15T10:00:00Z" }
  - Shopping cart: { "items": [...], "total": 125.50 }
  - Form progress: { "current_step": 3, "completed_steps": [1, 2] }
  - Expires at: "2024-01-15T18:00:00Z"

27.2 JSON Schema-Style Structural Definition
The following schema is intentionally minimal. It defines the core document structure and the essential entity forms required by Ontology v0.1.
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://blueprint-architecture.org/schema/system-ontology-v0.1.json",
  "title": "System Ontology v0.1",
  "type": "object",
  "required": ["ontology", "blueprint", "system", "entities", "relations"],
  "properties": {
    "ontology": {
      "type": "object",
      "required": ["id", "version", "title"],
      "properties": {
        "id": { "type": "string" },
        "version": { "type": "string" },
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["draft", "stable", "deprecated"] }
      }
    },
    "blueprint": {
      "type": "object",
      "required": ["id", "name", "ontology_version"],
      "properties": {
        "id": { "type": "string" },
        "name": { "type": "string" },
        "ontology_version": { "type": "string" },
        "system_type": { "type": "string" },
        "architecture_style": { "type": "string" },
        "description": { "type": "string" }
      }
    },
    "system": {
      "$ref": "#/$defs/systemEntity"
    },
    "context": {
      "type": "object",
      "properties": {
        "external_entities": {
          "type": "array",
          "items": { "$ref": "#/$defs/contextEntity" }
        }
      }
    },
    "entities": {
      "type": "array",
      "items": { "$ref": "#/$defs/entity" }
    },
    "relations": {
      "type": "array",
      "items": { "$ref": "#/$defs/relation" }
    },
    "projections": {
      "type": "object",
      "additionalProperties": {
        "$ref": "#/$defs/projection"
      }
    },
    "governance": {
      "type": "object",
      "properties": {
        "naming_convention": { "type": "object" },
        "compatibility": { "type": "object" },
        "deprecated": {
          "type": "array",
          "items": { "type": "string" }
        }
      }
    }
  },
  "$defs": {
    "baseEntity": {
      "type": "object",
      "required": ["id", "type", "name"],
      "properties": {
        "id": { "type": "string" },
        "type": { "type": "string" },
        "name": { "type": "string" },
        "description": { "type": "string" }
      }
    },
    "systemEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "System" },
            "goal": { "type": "string" },
            "boundary": {
              "type": "object",
              "properties": {
                "inside": {
                  "type": "array",
                  "items": { "type": "string" }
                },
                "interfaces": {
                  "type": "array",
                  "items": { "type": "string" }
                },
                "outside": {
                  "type": "array",
                  "items": { "type": "string" }
                }
              }
            }
          }
        }
      ]
    },
    "contextEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "role": { "type": "string" }
          }
        }
      ]
    },
    "capabilityEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "Capability" },
            "parent": {
              "type": ["string", "null"]
            }
          }
        }
      ]
    },
    "componentEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "Component" },
            "component_type": { "type": "string" },
            "responsibility": { "type": "string" },
            "inputs": {
              "type": "array",
              "items": { "type": "string" }
            },
            "outputs": {
              "type": "array",
              "items": { "type": "string" }
            },
            "statefulness": {
              "type": "string",
              "enum": ["stateless", "session_state", "stateful", "persistent"]
            }
          }
        }
      ]
    },
    "interfaceEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "Interface" },
            "interface_type": { "type": "string" },
            "protocol": { "type": "string" },
            "version": { "type": "string" },
            "contract_ref": { "type": "string" }
          }
        }
      ]
    },
    "contractEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "Contract" },
            "contract_type": { "type": "string" },
            "data_contract": { "type": "object" },
            "behavior_contract": { "type": "object" }
          }
        }
      ]
    },
    "dataEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "DataEntity" },
            "data_kind": {
              "type": "string",
              "enum": ["business", "technical"]
            },
            "persistence": {
              "type": "string",
              "enum": ["transient", "session", "persistent"]
            },
            "owner": { "type": "string" }
          }
        }
      ]
    },
    "workflowEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "enum": ["Workflow", "Task", "Job", "Step", "Trigger"] },
            "workflow_ref": { "type": "string" },
            "trigger_ref": { "type": "string" },
            "trigger_type": { "type": "string" },
            "order": { "type": "integer" }
          }
        }
      ]
    },
    "constraintEntity": {
      "allOf": [
        { "$ref": "#/$defs/baseEntity" },
        {
          "properties": {
            "type": { "const": "Constraint" },
            "metric": { "type": "string" },
            "threshold": { "type": "string" },
            "scope": {
              "type": "object",
              "properties": {
                "level": {
                  "type": "string",
                  "enum": ["system", "component", "interface", "workflow", "data"]
                },
                "target_ref": { "type": "string" }
              },
              "required": ["level", "target_ref"]
            }
          }
        }
      ]
    },
    "entity": {
      "oneOf": [
        { "$ref": "#/$defs/capabilityEntity" },
        { "$ref": "#/$defs/componentEntity" },
        { "$ref": "#/$defs/interfaceEntity" },
        { "$ref": "#/$defs/contractEntity" },
        { "$ref": "#/$defs/dataEntity" },
        { "$ref": "#/$defs/workflowEntity" },
        { "$ref": "#/$defs/constraintEntity" }
      ]
    },
    "relation": {
      "type": "object",
      "required": ["type", "source", "target"],
      "properties": {
        "type": {
          "type": "string",
          "enum": [
            "contains",
            "part_of",
            "depends_on",
            "calls",
            "invokes",
            "emits",
            "consumes",
            "reads",
            "writes",
            "owns",
            "governs",
            "implements",
            "conforms_to"
          ]
        },
        "source": { "type": "string" },
        "target": { "type": "string" },
        "evidence": {
          "type": "array",
          "items": { "type": "string" }
        },
        "confidence": {
          "type": "number",
          "minimum": 0,
          "maximum": 1
        }
      }
    },
    "projection": {
      "type": "object",
      "properties": {
        "focus": {
          "type": "array",
          "items": { "type": "string" }
        }
      }
    }
  }
}
